mapper.select:
SELECT * FROM merchant_payment_account
WHERE merchant_id = #{merchantId}
ORDER BY is_default DESC, create_time DESC

mapper.update:
UPDATE merchant_payment_account
account_type = #{accountType}, account_name = #{accountName}, account_number = #{accountNumber}, bank_name = #{bankName}, bank_branch = #{bankBranch}, is_default = #{isDefault}, status = #{status}, update_time = NOW()
WHERE id = #{id}
